const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const origin='https://leakendia.com';
export function card(s){return `<article><h2><a href="/marketplace/service/${e(s.slug)}">${e(s.title)}</a></h2><p>${e(s.summary)}</p>${s.price_minor==null?'':`<p>From $${(s.price_minor/100).toFixed(2)}</p>`}</article>`;}
export function layout({title,description,path,body,noindex=false,status=200}){return new Response(`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${e(title)}</title><meta name="description" content="${e(description)}"><link rel="canonical" href="${origin}${e(path)}">${noindex?'<meta name="robots" content="noindex,follow">':''}<link rel="stylesheet" href="/pages/marketplace/marketplace.css"></head><body><header><a href="/">Leakendia</a> / <a href="/marketplace">Marketplace</a></header><main>${body}</main></body></html>`,{status,headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store'}});}
export function service(s){return layout({title:s.seo_title||s.title+' | Leakendia',description:s.seo_description||s.summary,path:'/marketplace/service/'+s.slug,body:`<h1>${e(s.title)}</h1><p>${e(s.description)}</p>${s.offers.map(o=>`<section><h2>${e(o.name)}</h2><p>${o.price_minor==null?'Custom quote':e(o.currency)+' '+(o.price_minor/100).toFixed(2)+(o.model==='weekly'?'/week':'')}</p></section>`).join('')}${s.content.map(c=>`<section><h2>${e(c.title)}</h2><p>${e(c.body)}</p></section>`).join('')}<a href="/contact">Contact Leakendia</a>`});}
export {e};
